<script setup lang="ts">
import {watch,onBeforeUnmount} from 'vue';import {useEditor,EditorContent} from '@tiptap/vue-3';import StarterKit from '@tiptap/starter-kit';import {Extension} from '@tiptap/core';import {Plugin,PluginKey} from '@tiptap/pm/state';import {Decoration,DecorationSet} from '@tiptap/pm/view';import {Bold,Italic,Heading2,List,Undo2,Redo2} from 'lucide-vue-next';
const props=defineProps<{modelValue:any;readonly?:boolean;highlightId?:string}>();const emit=defineEmits(['update:modelValue','selected']);
const Ids=Extension.create({name:'blockIds',addGlobalAttributes(){return [{types:['paragraph','heading'],attributes:{blockId:{default:null,parseHTML:e=>e.getAttribute('data-block-id'),renderHTML:a=>a.blockId?{'data-block-id':a.blockId}:{}}}}]},addProseMirrorPlugins(){return [new Plugin({appendTransaction:(_trs,_old,state)=>{const tr=state.tr;let changed=false;const seen=new Set<string>();state.doc.descendants((node,pos)=>{if(['paragraph','heading'].includes(node.type.name)){let id=node.attrs.blockId;if(!id||seen.has(id)){id=crypto.randomUUID();tr.setNodeMarkup(pos,undefined,{...node.attrs,blockId:id});changed=true}seen.add(id)}});return changed?tr:null}})]}});
const highlightKey=new PluginKey('feedbackHighlight');
const Highlight=Extension.create({name:'feedbackHighlight',addProseMirrorPlugins(){return [new Plugin({key:highlightKey,state:{init:()=>'',apply:(tr,old)=>tr.getMeta(highlightKey)??old},props:{decorations:state=>{const id=highlightKey.getState(state);const nodes:Decoration[]=[];if(id)state.doc.descendants((node,pos)=>{if(node.attrs.blockId===id)nodes.push(Decoration.node(pos,pos+node.nodeSize,{class:'anchor-focus'}))});return DecorationSet.create(state.doc,nodes)}}})]}});
const editor=useEditor({content:props.modelValue,editable:!props.readonly,extensions:[StarterKit,Ids,Highlight],editorProps:{attributes:{class:'prose-editor','aria-label':props.readonly?'作品正文':'知识帖正文'}},onUpdate:({editor})=>emit('update:modelValue',editor.getJSON()),onSelectionUpdate:({editor})=>{const p=editor.state.selection.$from;for(let d=p.depth;d>=0;d--){const id=p.node(d).attrs.blockId;if(id){emit('selected',id);break}}}});
watch(()=>props.modelValue,v=>{if(editor.value&&JSON.stringify(v)!==JSON.stringify(editor.value.getJSON()))editor.value.commands.setContent(v,{emitUpdate:false})});watch(()=>props.readonly,v=>editor.value?.setEditable(!v));
watch(()=>props.highlightId,id=>{if(editor.value)editor.value.view.dispatch(editor.value.state.tr.setMeta(highlightKey,id||''))});
onBeforeUnmount(()=>editor.value?.destroy());
</script>
<template><div class="editor-shell"><div v-if="!readonly&&editor" class="editor-toolbar" aria-label="正文格式"><button type="button" title="加粗" aria-label="加粗" :class="{active:editor.isActive('bold')}" @click="editor.chain().focus().toggleBold().run()"><Bold :size="18"/></button><button type="button" title="斜体" aria-label="斜体" @click="editor.chain().focus().toggleItalic().run()"><Italic :size="18"/></button><span class="divider"></span><button type="button" title="二级标题" aria-label="二级标题" @click="editor.chain().focus().toggleHeading({level:2}).run()"><Heading2 :size="19"/></button><button type="button" title="列表" aria-label="无序列表" @click="editor.chain().focus().toggleBulletList().run()"><List :size="19"/></button><span class="grow"></span><button type="button" title="撤销" aria-label="撤销" @click="editor.chain().focus().undo().run()"><Undo2 :size="18"/></button><button type="button" title="重做" aria-label="重做" @click="editor.chain().focus().redo().run()"><Redo2 :size="18"/></button></div><EditorContent :editor="editor"/></div></template>
